package com.lamggm.rospocket;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31)
public class FreeGridLayoutTest {
 static JSONObject positioned()throws Exception{JSONObject j=new JSONObject(DashboardLayout.defaults().encode()).put("schema",4).put("columns",8);JSONArray a=j.getJSONArray("cards");int[][] pos={{0,0},{2,0},{4,0},{6,0},{0,4},{4,4},{4,7}};for(int i=0;i<7;i++)a.getJSONObject(i).put("column",pos[i][0]).put("row",pos[i][1]);return LegacyCodecFixtures.layout(j);}
 static JSONObject row(DashboardLayout l,String id)throws Exception{JSONArray a=new JSONObject(l.encode()).getJSONArray("cards");for(int i=0;i<7;i++)if(a.getJSONObject(i).getString("id").equals(id))return a.getJSONObject(i);throw new AssertionError();}
 @Test public void freeCellsAndEmptyRowsSurviveTheStrictPortableCodec()throws Exception{DashboardLayout l=DashboardLayout.decode(positioned().toString());assertEquals(2,row(l,"watch1").getInt("column"));assertEquals(4,row(l,"robot").getInt("row"));assertEquals(8,new JSONObject(l.encode()).getInt("columns"));assertEquals(l.encode(),DashboardLayout.decode(l.encode()).encode());}
 @Test public void occupiedMalformedAndOutOfBoundsPositionsAreRejected()throws Exception{for(String key:new String[]{"column","row"})for(Object bad:new Object[]{true,0.5,-2,1000,JSONObject.NULL}){JSONObject j=positioned();j.getJSONArray("cards").getJSONObject(0).put(key,bad);assertThrows(IllegalArgumentException.class,()->DashboardLayout.decode(j.toString()));}JSONObject overlap=positioned();overlap.getJSONArray("cards").getJSONObject(1).put("column",0);assertThrows(IllegalArgumentException.class,()->DashboardLayout.decode(overlap.toString()));JSONObject edge=positioned();edge.getJSONArray("cards").getJSONObject(4).put("row",63);assertThrows(IllegalArgumentException.class,()->DashboardLayout.decode(edge.toString()));}
 @Test public void narrowProjectionDoesNotRewriteSavedHolesAndResizeRetainsNames()throws Exception{DashboardLayout original=DashboardLayout.decode(positioned().toString()).rename("watch0","Velocidade");String before=original.encode();DashboardLayout phone=original.project(2);assertEquals(before,original.encode());assertEquals(2,phone.columns);DashboardLayout.decode(phone.encode());assertEquals(before,original.project(8).encode());DashboardLayout changed=original.position("watch0",7,12).resize("watch0",2,2);assertEquals("Velocidade",changed.get("watch0").name);DashboardLayout.decode(changed.encode());assertEquals(12,changed.get("watch0").row);}
}
